#!/bin/sh
# build.sh - THE ONE ENGINE of the repo root views of the two tree folders.
#
#   00_repos-tree/          repos-tree.{json,md,html,...}          (rendered by 0_registry/render-repos-tree.js)
#   01_repo-folders-tree/   repo-folders-tree.{json,md,html}       (rendered by 0_registry/render-folders-tree.js)
#
# Step 1  render: `node 0_registry/gen-registry.js --no-consumers` re-renders every generated file from the one master
#         0_registry/projects-repos.json (it calls the two renderers above; no rewrite, no network, no sibling-clone
#         writes). The folder data inside the master is refreshed separately and only on demand:
#         `./build.sh --refresh` runs `node 0_registry/refresh-folders-tree.js` first (needs `gh`, network).
# Step 2  deploy: the .json, .md and .html of each folder are COPIED (real files, never symlinks) to the repo root:
#         repos-tree.{json,md,html} and repo-folders-tree.{json,md,html}. The .md and .html copies carry a one-line
#         "generated by build.sh" comment (after the YAML frontmatter in the .md, after the doctype in the .html);
#         the .json copies are byte-copies (JSON has no comments; see README.md).
# Idempotent: a second run changes nothing. Drift guard: 9_others/test/test-root-copies.sh.
#   ./build.sh            render + deploy          ./build.sh --refresh    refresh folder data, render + deploy
set -eu
ROOT="$(cd "$(dirname "$0")" && pwd)"
cd "$ROOT"

[ "${1:-}" = "--refresh" ] && node 0_registry/refresh-folders-tree.js
node 0_registry/gen-registry.js --no-consumers

NOTE='generated by build.sh - edit the json source in 00_repos-tree/ or 01_repo-folders-tree/ (master: 0_registry/projects-repos.json), never this copy'

# stamp <src> <dst>: copy src to dst; .md/.html get the note, everything else is a byte copy
stamp() {
  src="$1"; dst="$2"; tmp="$dst.tmp.$$"
  case "$src" in
    *.md) awk -v n="<!-- $NOTE -->" '
        NR == 1 && $0 == "---" { fm = 1; print; next }
        fm && $0 == "---" { fm = 0; print; print n; done = 1; next }
        NR == 1 { print n; done = 1 }
        { print }' "$src" > "$tmp" ;;
    *.html) awk -v n="<!-- $NOTE -->" '{ print } NR == 1 { print n }' "$src" > "$tmp" ;;
    *) cp "$src" "$tmp" ;;
  esac
  if [ -f "$dst" ] && [ ! -L "$dst" ] && cmp -s "$tmp" "$dst"; then rm -f "$tmp"; else rm -f "$dst"; mv "$tmp" "$dst"; echo "deployed $dst"; fi
}

for pair in 00_repos-tree:repos-tree 01_repo-folders-tree:repo-folders-tree; do
  dir="${pair%%:*}"; base="${pair##*:}"
  for ext in json md html; do stamp "$dir/$base.$ext" "$ROOT/$base.$ext"; done
done
echo "build.sh: root copies up to date"
